param([Parameter(Mandatory=$true)][string]$CsvPath,[Parameter(Mandatory=$true)][string]$OutPath,[string]$Variant='UNKNOWN',[string]$RuntimeSha256='')
$ErrorActionPreference='Stop';$inv=[Globalization.CultureInfo]::InvariantCulture
function ParseD([object]$v){$x=0.0;[double]::TryParse(([string]$v),[Globalization.NumberStyles]::Float,$inv,[ref]$x)|Out-Null;return $x};function Median([double[]]$a){if(-not $a -or $a.Count -eq 0){return [double]::NaN};$s=@($a|Sort-Object);$n=$s.Count;$m=[int]($n/2);if(($n%2)-eq 1){return [double]$s[$m]};return ([double]$s[$m-1]+[double]$s[$m])/2.0};function F([double]$v){if([double]::IsNaN($v)){return 'NaN'};return $v.ToString('0.000',$inv)}
$rows=@(Import-Csv -LiteralPath $CsvPath);$r=0;$g=0;$rr=0;$rg=0;$gr=0;$gg=0;$clean=0;$rDw=New-Object 'System.Collections.Generic.List[double]';$gDw=New-Object 'System.Collections.Generic.List[double]';$pairImb=New-Object 'System.Collections.Generic.List[double]';$prev=$null;$prevDwell=0.0;$runType=$null;$runLen=0;$maxR=0;$maxG=0;$sumR=0.0;$sumG=0.0;$firstStart=$null;$lastEnd=$null
foreach($row in $rows){$t=[string]$row.type;if($t -ne 'R' -and $t -ne 'G'){continue};$dw=ParseD $row.dwell_ms;$st=ParseD $row.start_ms;if($null -eq $firstStart){$firstStart=$st};$lastEnd=$st+$dw;if($t -eq 'R'){$r++;$rDw.Add($dw);$sumR+=$dw}else{$g++;$gDw.Add($dw);$sumG+=$dw};if($runType -eq $t){$runLen++}else{if($runType -eq 'R' -and $runLen -gt $maxR){$maxR=$runLen};if($runType -eq 'G' -and $runLen -gt $maxG){$maxG=$runLen};$runType=$t;$runLen=1};if($null -ne $prev){$cont=0;try{$cont=[int]$row.transition_observer_contaminated}catch{$cont=0};if($cont -eq 0){$clean++;if($prev -eq 'R' -and $t -eq 'R'){$rr++}elseif($prev -eq 'R' -and $t -eq 'G'){$rg++}elseif($prev -eq 'G' -and $t -eq 'R'){$gr++}elseif($prev -eq 'G' -and $t -eq 'G'){$gg++};if($prev -ne $t){$den=($prevDwell+$dw)/2.0;if($den -gt 0){$pairImb.Add(100.0*[Math]::Abs($prevDwell-$dw)/$den)}}}};$prev=$t;$prevDwell=$dw}
if($runType -eq 'R' -and $runLen -gt $maxR){$maxR=$runLen};if($runType -eq 'G' -and $runLen -gt $maxG){$maxG=$runLen};$delta=[Math]::Abs($r-$g);$rMed=Median $rDw.ToArray();$gMed=Median $gDw.ToArray();$imbMed=Median $pairImb.ToArray();$timeBalance=0.0;if(($sumR+$sumG)-gt 0){$timeBalance=100.0*(1.0-[Math]::Abs($sumR-$sumG)/($sumR+$sumG))};$medBalance=0.0;if(($rMed+$gMed)-gt 0 -and -not [double]::IsNaN($rMed) -and -not [double]::IsNaN($gMed)){$medBalance=100.0*(1.0-[Math]::Abs($rMed-$gMed)/(($rMed+$gMed)/2.0))};$dur=0.0;if($null -ne $firstStart -and $null -ne $lastEnd){$dur=$lastEnd-$firstStart};$vf=0.0;$rf=0.0;$gf=0.0;if($dur -gt 0){$vf=1000.0*($r+$g)/$dur;$rf=1000.0*$r/$dur;$gf=1000.0*$g/$dur};$mult=0.0;if($rf -gt 0){$mult=$vf/$rf};$alt=($rr -eq 0 -and $gg -eq 0 -and $maxR -le 1 -and $maxG -le 1);$countBal=($delta -le 2);$timeBal=($timeBalance -ge 95.0);$medBal=($medBalance -ge 90.0);$result=$(if($alt -and $countBal -and $timeBal -and $medBal){'PASS'}else{'FAIL'})
$lines=New-Object 'System.Collections.Generic.List[string]';function Add([string]$k,[object]$v){$lines.Add($k+'='+[string]$v)};Add 'DIAGNOSTIC' 'PRESENTSHED1_VISIBLE_MARKER_DERIVED';Add 'VARIANT' $Variant;Add 'RUNTIME_SHA256' $RuntimeSha256;Add 'ROWS' $rows.Count;Add 'REAL' $r;Add 'GENERATED' $g;Add 'ABS_R_G_DELTA' $delta;Add 'VISIBLE_FPS_EST' (F $vf);Add 'REAL_FPS_EST' (F $rf);Add 'GENERATED_FPS_EST' (F $gf);Add 'VISIBLE_MULTIPLIER_VS_REAL' (F $mult);Add 'CLEAN_TRANSITIONS' $clean;Add 'R_TO_G' $rg;Add 'G_TO_R' $gr;Add 'R_TO_R' $rr;Add 'G_TO_G' $gg;Add 'MAX_R_STREAK' $maxR;Add 'MAX_G_STREAK' $maxG;Add 'REAL_DWELL_MEDIAN_MS' (F $rMed);Add 'GENERATED_DWELL_MEDIAN_MS' (F $gMed);Add 'TOTAL_REAL_DWELL_MS' (F $sumR);Add 'TOTAL_GENERATED_DWELL_MS' (F $sumG);Add 'TOTAL_DWELL_BALANCE_PCT' (F $timeBalance);Add 'MEDIAN_DWELL_BALANCE_PCT' (F $medBalance);Add 'ALTERNATING_PAIR_IMBALANCE_MEDIAN_PCT' (F $imbMed);Add 'ALTERNATION_GATE' $(if($alt){'PASS'}else{'FAIL'});Add 'COUNT_BALANCE_GATE' $(if($countBal){'PASS'}else{'FAIL'});Add 'TOTAL_DWELL_BALANCE_GATE' $(if($timeBal){'PASS'}else{'FAIL'});Add 'MEDIAN_DWELL_BALANCE_GATE' $(if($medBal){'PASS'}else{'FAIL'});Add 'FLUIDITY_VISIBLE_RESULT' $result;[IO.File]::WriteAllLines($OutPath,$lines.ToArray(),(New-Object Text.UTF8Encoding($false)));exit 0
